                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // Otherwise it makes a nested call so msg.sender on c is not the admin.
            (bool ok, ) = address(this).call(
                abi.encodeWithSelector(this.nestedSetOwner.selector, newOwner)
            );
            reverted = !ok;
