        if (asAdmin) {
            assert(!reverted && afterOwner == newOwner);
        } else {
            assert(reverted && afterOwner == beforeOwner);
        }
    }

    function nestedSetOwner(address newOwner) external {
        c.setOwner(newOwner);
    }

    receive() external payable {}
}

