contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address newOwner) public {
        require(caller != address(0) && newOwner != address(0));

        // The test contract is the admin, so calls on c are made with msg.sender == admin
        // when the test itself calls c. To simulate a different caller we cannot change
        // msg.sender, so we only test the admin path here: the admin call must succeed
        // and update owner; a non-admin call is impossible to drive from this test
        // because msg.sender is always this contract.
        //
        // Therefore the rule we can assert for every input is:
        // when the admin (this contract) calls setOwner(newOwner), it returns true
        // and changes c.owner() to newOwner.

        address beforeOwner = c.owner();

